33	// handleUpsert stores a registration or an update for one service instance.
34	// Repeating the same (service name, instance id) pair overwrites the record.
35	func (s *Server) handleUpsert(c *gin.Context) {
36		bag, apiErr := buildParamBag(c)
37		if apiErr != nil {
38			writeError(c, apiErr)
39			return
40		}
41	
42		// A path locator wins and cannot be changed by body or query fields; the
43		// collection entry POST .../services/{serviceName}/instances carries no
44		// instance segment, so instance_id keeps its body/query lookup there.
45		serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
46		if apiErr != nil {
47			writeError(c, apiErr)
48			return
49		}
50		instanceID, apiErr := bag.locateText("instanceId", instanceIDKeys, "instance_id must not be empty")
51		if apiErr != nil {
52			writeError(c, apiErr)
53			return
54		}
55		weightValue, ok := bag.get(weightKeys)
56		if !ok {
57			writeError(c, errInvalidParameter("weight must be a positive number"))
58			return
59		}
60		weight, ok := positiveNumber(weightValue)
61		if !ok {
62			writeError(c, errInvalidParameter("weight must be a positive number"))
63			return
64		}
65		port := int64(0)
66		if portValue, present := bag.get(portKeys); present {
67			port, ok = parsePortValue(portValue)
68			if !ok {
69				writeError(c, errInvalidParameter("port must be a non-negative integer"))
70				return
71			}
72		}
73		heartbeatValue, ok := bag.get(heartbeatKeys)
74		if !ok {
75			writeError(c, errInvalidParameter("heartbeat_at is required"))
76			return
77		}
78		heartbeatAt, ok := parseTimeValue(heartbeatValue)
79		if !ok {
80			writeError(c, errInvalidParameter("heartbeat_at must be a valid timestamp"))
81			return
82		}
83	
84		healthy := false
85		if healthValue, ok := bag.get(healthKeys); ok {
86			healthy, ok = strictBoolValue(healthValue)
87			if !ok {
88				writeError(c, errInvalidParameter("healthy must be a boolean true or false"))
89				return
90			}
91		}
92		address := ""
93		if addressValue, ok := bag.get(addressKeys); ok {
94			address = stringValue(addressValue)
95		}
96	
97		// evaluate_at is optional on registrations. The clock-skew guard rejects a
98		// heartbeat later than the caller's evaluation point.
99		if evaluateValue, ok := bag.get(evaluateAtKeys); ok {
100			evaluateAt, parsed := parseTimeValue(evaluateValue)
101			if !parsed {
102				writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
103				return
104			}
105			if evaluateAt.Before(heartbeatAt) {
106				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
107				return
108			}
109		}
110	
111		input := store.InstanceInput{
112			ServiceName: serviceName,
113			InstanceID:  instanceID,
114			Address:     address,
115			Port:        port,
116			Healthy:     healthy,
117			Weight:      weight,
118			HeartbeatAt: heartbeatAt,
119		}
120		instance, err := s.store.UpsertInstance(input)
121		if err != nil {
122			writeError(c, errStorageUnavailable())
123			return
124		}
125		c.JSON(200, gin.H{"instance": instanceJSON(instance)})
126	}
