140	// handleBatchUpsert registers or overwrites several instances of one service
141	// in one request. The body is exactly one JSON object; every entry is
142	// validated before any write, so an invalid batch changes no record, and the
143	// store applies the whole batch atomically.
144	func (s *Server) handleBatchUpsert(c *gin.Context, pathServiceName string, serviceNameFromPath bool) {
145		bag, apiErr := buildStrictObjectBag(c)
146		if apiErr != nil {
147			writeError(c, apiErr)
148			return
149		}
150		serviceName := pathServiceName
151		if !serviceNameFromPath {
152			serviceName, apiErr = bag.requiredText(serviceNameKeys, "service_name must not be empty")
153			if apiErr != nil {
154				writeError(c, apiErr)
155				return
156			}
157		} else if serviceName == "" {
158			writeError(c, errInvalidParameter("service_name must not be empty"))
159			return
160		}
161	
162		rawEntries, ok := bag.get([]string{"instances"})
163		if !ok {
164			writeError(c, errInvalidParameter("instances must be a non-empty list"))
165			return
166		}
167		entries, ok := rawEntries.([]any)
168		if !ok || len(entries) == 0 {
169			writeError(c, errInvalidParameter("instances must be a non-empty list"))
170			return
171		}
172	
173		inputs := make([]store.InstanceInput, 0, len(entries))
174		seen := make(map[string]struct{}, len(entries))
175		for _, rawEntry := range entries {
176			entry, ok := rawEntry.(map[string]any)
177			if !ok {
178				writeError(c, errInvalidParameter("each instance must be an object"))
179				return
180			}
181			instanceID := strings.TrimSpace(stringValue(entry["instance_id"]))
182			if instanceID == "" {
183				writeError(c, errInvalidParameter("instance_id must not be empty"))
184				return
185			}
186			if _, duplicated := seen[instanceID]; duplicated {
187				writeError(c, errInvalidParameter("instance_id must not be duplicated"))
188				return
189			}
190			weightValue, present := entry["weight"]
191			if !present {
192				writeError(c, errInvalidParameter("weight must be a positive number"))
193				return
194			}
195			weight, ok := positiveNumber(weightValue)
196			if !ok {
197				writeError(c, errInvalidParameter("weight must be a positive number"))
198				return
199			}
200			port := int64(0)
201			if portValue, present := entry["port"]; present {
202				port, ok = parsePortValue(portValue)
203				if !ok {
204					writeError(c, errInvalidParameter("port must be a non-negative integer"))
205					return
206				}
207			}
208			healthy := false
209			if healthValue, present := entry["healthy"]; present {
210				healthy, ok = strictBoolValue(healthValue)
211				if !ok {
212					writeError(c, errInvalidParameter("healthy must be a boolean true or false"))
213					return
214				}
215			}
216			heartbeatValue, present := entry["heartbeat_at"]
217			if !present {
218				writeError(c, errInvalidParameter("heartbeat_at is required"))
219				return
220			}
221			heartbeatAt, parsed := parseTimeValue(heartbeatValue)
222			if !parsed {
223				writeError(c, errInvalidParameter("heartbeat_at must be a valid timestamp"))
224				return
225			}
226			address := ""
227			if addressValue, present := entry["address"]; present {
228				address = stringValue(addressValue)
229			}
230			seen[instanceID] = struct{}{}
231			inputs = append(inputs, store.InstanceInput{
232				ServiceName: serviceName,
233				InstanceID:  instanceID,
234				Address:     address,
235				Port:        port,
236				Healthy:     healthy,
237				Weight:      weight,
238				HeartbeatAt: heartbeatAt,
239			})
240		}
241	
242		instances, err := s.store.UpsertInstances(inputs)
243		if err != nil {
244			writeError(c, errStorageUnavailable())
245			return
246		}
247		results := make([]gin.H, 0, len(instances))
248		for _, instance := range instances {
249			results = append(results, instanceJSON(instance))
250		}
251		c.JSON(200, gin.H{
252			"service_name": serviceName,
253			"registered":   len(results),
254			"instances":    results,
255		})
256	}
