111	// dangling "}" or "]" because those are not value tokens. A second Decode
112	// must therefore return exactly io.EOF, which is true only once the object
113	// has ended and nothing but whitespace remains.
114	func readStrictObjectBody(c *gin.Context) (map[string]any, *apiError) {
115		if c.Request.Body == nil {
116			return nil, errInvalidParameter("request body must be a JSON object")
117		}
118		raw, err := io.ReadAll(c.Request.Body)
119		if err != nil {
120			return nil, errInvalidParameter("request body cannot be read")
121		}
122		if len(bytes.TrimSpace(raw)) == 0 {
123			return nil, errInvalidParameter("request body must be a JSON object")
124		}
125		decoder := json.NewDecoder(bytes.NewReader(raw))
126		// UseNumber keeps every JSON number as its literal text so integer
127		// fields (port) can be parsed exactly, without the float64 rounding
128		// that json.Unmarshal would apply.
129		decoder.UseNumber()
130		var body map[string]any
131		if err := decoder.Decode(&body); err != nil || body == nil {
132			return nil, errInvalidParameter("request body must be a JSON object")
133		}
134		var trailing json.RawMessage
135		if err := decoder.Decode(&trailing); err != io.EOF {
136			return nil, errInvalidParameter("request body must be a single JSON object")
137		}
138		return body, nil
139	}
140	
141	// buildStrictObjectBag is a paramBag populated from exactly one JSON object:
142	// unlike buildParamBag it never reads query parameters, so a rejected or
143	// missing body field cannot be repaired through the URL. Path parameters are
144	// still recorded so path locators keep winning.
145	func buildStrictObjectBag(c *gin.Context) (*paramBag, *apiError) {
146		body, apiErr := readStrictObjectBody(c)
147		if apiErr != nil {
148			return nil, apiErr
149		}
150		bag := &paramBag{
151			values: make(map[string]any, len(body)),
152			path:   make(map[string]any),
153		}
154		for key, value := range body {
155			bag.values[key] = value
156		}
157		for _, param := range c.Params {
158			bag.path[param.Key] = param.Value
159		}
160		return bag, nil
161	}
162	
163	func (b *paramBag) get(keys []string) (any, bool) {
164		for _, key := range keys {
165			if value, ok := b.values[key]; ok {
166				return value, true
167			}
168		}
169		return nil, false
170	}
171	
172	// locateText resolves one locator field (service name or instance id). A
173	// value carried by the route path always wins: a conflicting, empty or
174	// non-string value of the same field in the body or query string is ignored,
175	// and a blank path segment is a parameter error that cannot be filled from
176	// another source. Only when the route carries no such segment does the field
177	// fall back to the existing body/query lookup rules.
178	func (b *paramBag) locateText(pathKey string, keys []string, message string) (string, *apiError) {
179		if raw, fromPath := b.path[pathKey]; fromPath {
180			text := strings.TrimSpace(stringValue(raw))
181			if text == "" {
182				return "", errInvalidParameter(message)
183			}
184			return text, nil
185		}
186		return b.requiredText(keys, message)
187	}
188	
189	// readJSONObject requires the request body to be a single JSON object. An
190	// empty body, a JSON array or any non-object payload is a parameter error.
191	// It is used by the batch entry points whose contract forbids merging query
192	// parameters or accepting a bare value.
193	func readJSONObject(c *gin.Context) (map[string]any, *apiError) {
194		if c.Request.Body == nil {
195			return nil, errInvalidParameter("request body must be a JSON object")
196		}
197		raw, err := io.ReadAll(c.Request.Body)
198		if err != nil {
199			return nil, errInvalidParameter("request body cannot be read")
200		}
201		if len(bytes.TrimSpace(raw)) == 0 {
202			return nil, errInvalidParameter("request body must be a JSON object")
203		}
204		var body map[string]any
205		if err := json.Unmarshal(raw, &body); err != nil || body == nil {
206			return nil, errInvalidParameter("request body must be a JSON object")
207		}
208		return body, nil
209	}
210	
211	func stringValue(value any) string {
212		if text, ok := value.(string); ok {
213			return text
214		}
215		return ""
216	}
217	
218	// readHealthyInput accepts a new healthy state for one instance from either a
219	// JSON body field ("healthy": true|false) or the ?healthy=true|false query
220	// parameter. The JSON field wins when both carry it. JSON accepts only
221	// booleans, while the query parameter accepts only the lowercase text "true"
222	// or "false"; every other representation is a parameter error.
223	func readHealthyInput(c *gin.Context) (bool, *apiError) {
224		queryValue, queryPresent := c.GetQuery("healthy")
225	
226		if c.Request.Body != nil {
227			raw, err := io.ReadAll(c.Request.Body)
228			if err != nil {
229				return false, errInvalidParameter("request body cannot be read")
230			}
231			if len(bytes.TrimSpace(raw)) > 0 {
232				var body map[string]any
233				if err := json.Unmarshal(raw, &body); err != nil || body == nil {
234					return false, errInvalidParameter("request body must be a JSON object")
235				}
236				if value, present := body["healthy"]; present {
237					healthy, ok := strictBoolValue(value)
238					if !ok {
239						return false, errInvalidParameter("healthy must be a boolean true or false")
240					}
241					return healthy, nil
242				}
243			}
244		}
245	
246		if !queryPresent {
247			return false, errInvalidParameter("healthy must be a boolean true or false")
248		}
249		switch queryValue {
250		case "true":
251			return true, nil
252		case "false":
253			return false, nil
254		default:
255			return false, errInvalidParameter("healthy must be a boolean true or false")
256		}
257	}
258	
259	// requiredText returns the trimmed text for the first matching key, or an error
260	// when the value is missing or blank.
261	func (b *paramBag) requiredText(keys []string, message string) (string, *apiError) {
262		value, ok := b.get(keys)
263		if !ok {
264			return "", errInvalidParameter(message)
265		}
266		text := strings.TrimSpace(stringValue(value))
267		if text == "" {
268			return "", errInvalidParameter(message)
269		}
270		return text, nil
271	}
272	
273	// positiveNumber accepts weights: only numbers strictly greater than zero.
274	func positiveNumber(value any) (float64, bool) {
275		number, ok := toFloat(value)
276		if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number <= 0 {
277			return 0, false
278		}
279		return number, true
280	}
281	
282	// parsePortValue accepts a non-negative integer port number in the range
283	// [0, 9223372036854775807]. JSON numbers and numeric strings are parsed from
284	// their decimal text with exact integer semantics: values above 2^53 keep
285	// their exact value, fractional forms such as 8080.0 or 8.08e3 collapse to
286	// their integer value, and the int64 bound is enforced without rounding, so
287	// 9223372036854775808 is rejected instead of overflowing the conversion.
288	func parsePortValue(value any) (int64, bool) {
289		switch typed := value.(type) {
290		case json.Number:
291			return parsePortText(typed.String())
292		case string:
293			return parsePortText(strings.TrimSpace(typed))
294		case float64:
295			// A float64 at or beyond 2^63 cannot be a valid port: the largest
296			// exactly representable candidate below it is 2^63-1024, and the
297			// int64 conversion of anything larger would overflow.
298			if math.IsNaN(typed) || math.IsInf(typed, 0) || typed != math.Trunc(typed) ||
299				typed < 0 || typed >= 9223372036854775808.0 {
300				return 0, false
301			}
302			return int64(typed), true
303		case int:
304			return int64(typed), typed >= 0
305		case int64:
306			return typed, typed >= 0
307		default:
308			return 0, false
309		}
310	}
311	
312	// portNumberPattern is the decimal grammar a port may use: an integer or a
313	// fixed/scientific decimal with an optional sign.
314	var portNumberPattern = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)
315	
316	// parsePortText parses the exact integer value of a decimal number without
317	// going through float64. The mantissa is kept as a digit string and the
318	// exponent as a small int, so huge exponents are rejected by digit counting
319	// instead of materializing enormous integers.
320	func parsePortText(text string) (int64, bool) {
321		// Fast path: a plain decimal integer, exact for the whole int64 range.
322		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
323			return number, number >= 0
324		}
325		if !portNumberPattern.MatchString(text) {
326			return 0, false
327		}
328		negative := strings.HasPrefix(text, "-")
329		mantissa := strings.TrimLeft(text, "+-")
330		exponent := 0
331		if at := strings.IndexAny(mantissa, "eE"); at >= 0 {
332			expText := mantissa[at+1:]
333			mantissa = mantissa[:at]
334			if digits := strings.TrimLeft(strings.TrimLeft(expText, "+-"), "0"); len(digits) > 6 {
335				// |exponent| >= 10^6: the value is either far beyond the int64
336				// bound or far below one; only an all-zero mantissa is still
337				// exactly zero.
338				if allZeroDigits(mantissa) {
339					return 0, true
340				}
341				return 0, false
342			}
343			exponent, _ = strconv.Atoi(expText)
344		}
345		intPart, fracPart := mantissa, ""
346		if at := strings.IndexByte(mantissa, '.'); at >= 0 {
347			intPart, fracPart = mantissa[:at], mantissa[at+1:]
348		}
349		// value = digits * 10^k
350		digits := intPart + fracPart
351		k := exponent - len(fracPart)
352		digits = strings.TrimLeft(digits, "0")
353		for strings.HasSuffix(digits, "0") {
354			digits = digits[:len(digits)-1]
355			k++
356		}
357		if digits == "" {
358			return 0, true // exact zero, in any form
359		}
360		if negative || k < 0 {
361			// A negative port is out of range; a negative remaining exponent
362			// leaves a fractional part, so the value is not an integer.
363			return 0, false
364		}
365		if len(digits)+k > 19 {
366			return 0, false
367		}
368		number, err := strconv.ParseInt(digits+strings.Repeat("0", k), 10, 64)
369		if err != nil {
370			return 0, false // 19 digits but beyond math.MaxInt64
371		}
372		return number, true
373	}
374	
375	// allZeroDigits reports whether a mantissa (digits with an optional dot)
376	// denotes zero.
377	func allZeroDigits(mantissa string) bool {
378		for _, r := range mantissa {
379			if r != '0' && r != '.' {
380				return false
381			}
382		}
383		return true
384	}
385	
386	// strictBoolValue accepts only JSON boolean true or false. Every other
387	// representation (text, numbers) is rejected so all implementations agree.
388	func strictBoolValue(value any) (bool, bool) {
389		typed, ok := value.(bool)
390		return typed, ok
391	}
392	
393	func toFloat(value any) (float64, bool) {
394		switch typed := value.(type) {
395		case float64:
396			return typed, true
397		case int:
398			return float64(typed), true
399		case int64:
400			return float64(typed), true
401		case json.Number:
402			number, err := typed.Float64()
403			if err != nil {
404				return 0, false
405			}
406			return number, true
407		case string:
408			number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
409			if err != nil {
410				return 0, false
411			}
412			return number, true
413		default:
414			return 0, false
415		}
416	}
417	
418	func parseHealthValue(value any) (bool, bool) {
419		switch typed := value.(type) {
420		case bool:
421			return typed, true
422		case float64:
423			switch typed {
424			case 1:
425				return true, true
426			case 0:
427				return false, true
428			}
429		case json.Number:
430			if number, err := typed.Float64(); err == nil {
431				switch number {
432				case 1:
433					return true, true
434				case 0:
435					return false, true
436				}
437			}
438		case string:
439			switch strings.ToLower(strings.TrimSpace(typed)) {
440			case "healthy", "up", "on", "true", "1", "yes":
441				return true, true
442			case "unhealthy", "down", "off", "false", "0", "no":
443				return false, true
444			}
445		}
446		return false, false
447	}
448	
449	// Accepted timestamps cover [0000-01-01T00:00:00Z, 10000-01-01T00:00:00Z)
450	// once converted to UTC: the lower bound is included, the upper bound is
451	// excluded. These are exactly the instants the RFC3339 storage format can
452	// write and read back, so anything outside could never round-trip.
453	var (
454		minAcceptedTime = time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
455		maxAcceptedTime = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
456	)
457	
458	func inAcceptedTimeRange(t time.Time) bool {
459		t = t.UTC()
460		return !t.Before(minAcceptedTime) && t.Before(maxAcceptedTime)
461	}
462	
463	func parseTimeValue(value any) (time.Time, bool) {
464		switch typed := value.(type) {
465		case string:
466			text := strings.TrimSpace(typed)
467			if text == "" {
468				return time.Time{}, false
469			}
470			if number, err := strconv.ParseFloat(text, 64); err == nil {
471				return unixTimeInRange(number)
472			}
473			for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
474				if parsed, err := time.Parse(layout, text); err == nil {
475					if !inAcceptedTimeRange(parsed) {
476						return time.Time{}, false
477					}
478					return parsed, true
479				}
480			}
481		case float64:
482			return unixTimeInRange(typed)
483		case json.Number:
484			number, err := typed.Float64()
485			if err != nil {
486				return time.Time{}, false
487			}
488			return unixTimeInRange(number)
489		}
490		return time.Time{}, false
491	}
492	
493	// unixTimeInRange converts a Unix second count that lands inside the
494	// accepted range. The range check runs on the float itself, before any int64
495	// conversion, so non-finite values (NaN, Inf, Infinity with any sign) and
496	// out-of-range finite values are rejected instead of overflowing and
497	// wrapping back into a valid-looking date.
498	func unixTimeInRange(seconds float64) (time.Time, bool) {
499		if math.IsNaN(seconds) || math.IsInf(seconds, 0) ||
500			seconds < float64(minAcceptedTime.Unix()) || seconds >= float64(maxAcceptedTime.Unix()) {
501			return time.Time{}, false
502		}
503		return unixTime(seconds), true
504	}
505	
506	func unixTime(seconds float64) time.Time {
507		whole := int64(seconds)
508		fraction := seconds - float64(whole)
509		return time.Unix(whole, int64(fraction*1e9)).UTC()
510	}
511	
512	// parseTimeout accepts a number of seconds or a duration string such as "30s".
513	// A non-positive duration is reported as invalid by the caller.
514	func parseTimeout(value any) (time.Duration, bool) {
515		switch typed := value.(type) {
516		case float64:
517			if math.IsNaN(typed) || math.IsInf(typed, 0) {
518				return 0, false
519			}
520			return time.Duration(typed * float64(time.Second)), true
521		case json.Number:
522			number, err := typed.Float64()
523			if err != nil || math.IsNaN(number) || math.IsInf(number, 0) {
524				return 0, false
525			}
526			return time.Duration(number * float64(time.Second)), true
527		case string:
528			text := strings.TrimSpace(typed)
529			if text == "" {
530				return 0, false
531			}
532			if duration, err := time.ParseDuration(text); err == nil {
533				return duration, true
534			}
535			if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
536				return time.Duration(number * float64(time.Second)), true
537			}
538		}
539		return 0, false
540	}
