11	// Complete, otherwise-valid batch bodies. The register batch mixes an
12	// overwrite of the existing i-1 with creation of i-3; accepting any of them
13	// would either rewrite i-1 or create i-3, so a rejection leaves both visible.
14	const registerTrailerObjectByPath = `{"instances":[` +
15		`{"instance_id":"i-1","address":"10.0.0.1:9000","port":9000,"healthy":false,"weight":77,"heartbeat_at":"2026-10-01T12:30:00Z"},` +
16		`{"instance_id":"i-3","address":"10.0.0.3:9003","port":9003,"healthy":true,"weight":88,"heartbeat_at":"2026-10-01T12:31:00Z"}]}`
17	
18	const registerTrailerObjectByBody = `{"service_name":"svc","instances":[` +
19		`{"instance_id":"i-1","address":"10.0.0.1:9000","port":9000,"healthy":false,"weight":77,"heartbeat_at":"2026-10-01T12:30:00Z"},` +
20		`{"instance_id":"i-3","address":"10.0.0.3:9003","port":9003,"healthy":true,"weight":88,"heartbeat_at":"2026-10-01T12:31:00Z"}]}`
21	
22	const weightTrailerObject = `{"updates":[` +
23		`{"instance_id":"i-1","weight":55},` +
24		`{"instance_id":"i-2","weight":66}]}`
25	
26	type batchEndpoint struct {
27		name   string
28		method string
29		path   string
30		object string
31	}
32	
33	func bodyIntegrityEndpoints() []batchEndpoint {
34		return []batchEndpoint{
35			{"register-path", http.MethodPost, "/api/v1/services/svc/instances/batch", registerTrailerObjectByPath},
36			{"register-body", http.MethodPost, "/api/v1/register/batch", registerTrailerObjectByBody},
37			{"weight", http.MethodPut, "/api/v1/services/svc/instances/weight", weightTrailerObject},
38		}
39	}
40	
41	// publicInstance fetches a full record through the public GET entry. A 404
42	// reports found=false so rejected batches can be proven not to create rows.
43	func publicInstance(t *testing.T, router http.Handler, service, id string) (map[string]any, bool) {
44		t.Helper()
45		rec := doRequest(t, router, http.MethodGet,
46			fmt.Sprintf("/api/v1/services/%s/instances/%s", service, id), nil)
47		switch rec.Code {
48		case http.StatusOK:
49			return decodeBody(t, rec)["instance"].(map[string]any), true
50		case http.StatusNotFound:
51			return nil, false
52		default:
53			t.Fatalf("GET %s/%s: status %d body %s", service, id, rec.Code, rec.Body.String())
54			return nil, false
55		}
56	}
57	
58	// assertOriginalI1 verifies every field of the pre-existing svc/i-1 record
59	// through the public query, proving a rejected request performed no overwrite.
60	func assertOriginalI1(t *testing.T, inst map[string]any) {
61		t.Helper()
62		if inst["service_name"] != "svc" || inst["instance_id"] != "i-1" ||
63			inst["address"] != "10.0.0.8:8080" || inst["port"].(float64) != 8080 ||
64			inst["healthy"] != true || inst["weight"].(float64) != 10 ||
65			inst["heartbeat_at"] != baseTime {
66			t.Fatalf("svc/i-1 changed after rejected request: %v", inst)
67		}
68	}
69	
70	// TestBatchEntriesRejectDataAfterObject covers the integrity gap: a complete
71	// valid object followed immediately or after JSON whitespace by a stray "}",
72	// "]", a second object or null must be rejected on all three batch entries,
73	// and the rejection must leave no partial write behind.
74	func TestBatchEntriesRejectDataAfterObject(t *testing.T) {
75		trailers := []string{"}", "]", "{}", "null", " }", "\t]\n", " {}", " null"}
76	
77		for _, ep := range bodyIntegrityEndpoints() {
78			router, st := testRouter(t)
79			registerInstance(t, router, weightRecord())
80			second := weightRecord()
81			second["instance_id"] = "i-2"
82			second["weight"] = 3
83			registerInstance(t, router, second)
84			other := weightRecord()
85			other["service_name"] = "other"
86			registerInstance(t, router, other)
87	
88			for _, trailer := range trailers {
89				t.Run(ep.name+"+"+fmt.Sprintf("%q", trailer), func(t *testing.T) {
90					rec := doRawRequest(t, router, ep.method, ep.path, ep.object+trailer)
91					expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
92	
93					// Existing instances keep every field; no new instance appears.
94					got, found := publicInstance(t, router, "svc", "i-1")
95					if !found {
96						t.Fatalf("svc/i-1 disappeared after rejected request")
97					}
98					assertOriginalI1(t, got)
99					i2, found := publicInstance(t, router, "svc", "i-2")
100					if !found || i2["weight"].(float64) != 3 {
101						t.Fatalf("svc/i-2 changed after rejected request: %v found=%v", i2, found)
102					}
103					if _, found := publicInstance(t, router, "svc", "i-3"); found {
104						t.Fatalf("rejected register batch created svc/i-3")
105					}
106					// Records of another service are untouched.
107					peer, found := publicInstance(t, router, "other", "i-1")
108					if !found || peer["weight"].(float64) != 10 {
109						t.Fatalf("other/i-1 changed after rejected request: %v found=%v", peer, found)
110					}
111					// The store still reports exactly the three pre-existing rows.
112					if all, err := st.ListAllInstances(); err != nil || len(all) != 3 {
113						t.Fatalf("store rows = %d (err %v), want 3", len(all), err)
114					}
115				})
116			}
117		}
118	}
119	
120	// TestBatchEntriesRejectNonObjectBodies covers empty, whitespace-only and
121	// bare-value bodies. Query parameters must not be able to repair any of them.
122	func TestBatchEntriesRejectNonObjectBodies(t *testing.T) {
123		bodies := []string{
124			"", "   ", "\t\r\n ",
125			"null", "[]", "[{}]", "123", "true", `"text"`, "{bad",
126		}
127	
128		for _, ep := range bodyIntegrityEndpoints() {
129			router, _ := testRouter(t)
130			registerInstance(t, router, weightRecord())
131			second := weightRecord()
132			second["instance_id"] = "i-2"
133			second["weight"] = 3
134			registerInstance(t, router, second)
135	
136			for _, raw := range bodies {
137				t.Run(ep.name+"+"+fmt.Sprintf("%q", raw), func(t *testing.T) {
138					rec := doRawRequest(t, router, ep.method, ep.path, raw)
139					expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
140					got, found := publicInstance(t, router, "svc", "i-1")
141					if !found {
142						t.Fatalf("svc/i-1 disappeared")
143					}
144					assertOriginalI1(t, got)
145					if i2, found := publicInstance(t, router, "svc", "i-2"); !found || i2["weight"].(float64) != 3 {
146						t.Fatalf("svc/i-2 changed after rejected request: %v found=%v", i2, found)
147					}
148					if _, found := publicInstance(t, router, "svc", "i-3"); found {
149						t.Fatalf("rejected request created svc/i-3")
150					}
151				})
152			}
153		}
154	
155		// Query parameters cannot rescue a body that is not one JSON object.
156		router, _ := testRouter(t)
157		registerInstance(t, router, weightRecord())
158		rescueCases := []struct {
159			method string
160			path   string
161			body   string
162		}{
163			{http.MethodPost, "/api/v1/register/batch?service_name=svc", ""},
164			{http.MethodPost, "/api/v1/register/batch?service_name=svc", "null"},
165			{http.MethodPost, "/api/v1/register/batch?service_name=svc", registerTrailerObjectByBody + "}"},
166			{http.MethodPut, "/api/v1/services/svc/instances/weight?weight=5", ""},
167			{http.MethodPut, "/api/v1/services/svc/instances/weight?weight=5", "null"},
168			{http.MethodPut, "/api/v1/services/svc/instances/weight?weight=5", weightTrailerObject + "]"},
169		}
170		for _, rc := range rescueCases {
171			rec := doRawRequest(t, router, rc.method, rc.path, rc.body)
172			expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
173			got, found := publicInstance(t, router, "svc", "i-1")
174			if !found {
175				t.Fatalf("svc/i-1 disappeared after %s %s", rc.method, rc.path)
176			}
177			if got["weight"].(float64) != 10 {
178				t.Fatalf("query parameter rescued an invalid body: %v", got)
179			}
180		}
181	}
182	
183	// TestBatchEntriesAcceptWhitespaceAroundObject ensures leading and trailing
184	// JSON whitespace (spaces, tabs, newlines, carriage returns) around an
185	// otherwise valid object still succeeds on every batch entry.
186	func TestBatchEntriesAcceptWhitespaceAroundObject(t *testing.T) {
187		wrappers := []string{"  %s  ", "\t%s\n", "\r\n\t %s \r\n"}
188	
189		t.Run("register", func(t *testing.T) {
190			router, _ := testRouter(t)
191			for i, wrap := range wrappers {
192				id := fmt.Sprintf("i-w%d", i)
193				for _, target := range []string{
194					"/api/v1/services/svc/instances/batch",
195					"/api/v1/register/batch",
196				} {
197					var raw string
198					if strings.HasPrefix(target, "/api/v1/services/") {
199						raw = fmt.Sprintf(wrap, fmt.Sprintf(
200							`{"instances":[{"instance_id":%q,"weight":10,"heartbeat_at":%q}]}`,
201							id, baseTime))
202					} else {
203						raw = fmt.Sprintf(wrap, fmt.Sprintf(
204							`{"service_name":"svc","instances":[{"instance_id":%q,"weight":10,"heartbeat_at":%q}]}`,
205							id, baseTime))
206					}
207					rec := doRawRequest(t, router, http.MethodPost, target, raw)
208					if rec.Code != http.StatusOK {
209						t.Fatalf("%s wrapped body %q: status %d body %s", target, raw, rec.Code, rec.Body.String())
210					}
211					got, found := publicInstance(t, router, "svc", id)
212					if !found || got["weight"].(float64) != 10 {
