1	package api
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"path/filepath"
8		"strings"
9		"testing"
10	
11		"github.com/luwa07832/service-discovery-api/internal/store"
12	)
13	
14	// portBody builds a registration body whose port is the given raw value.
15	func portBody(id string, port any) map[string]any {
16		return map[string]any{
17			"service_name": "svc",
18			"instance_id":  id,
19			"weight":       10,
20			"heartbeat_at": at(0),
21			"port":         port,
22		}
23	}
24	
25	func TestPortExactIntegerForms(t *testing.T) {
26		router, st := testRouter(t)
27		cases := []struct {
28			name string
29			raw  string
30			want int64
31		}{
32			{"plain integer", "8080", 8080},
33			{"zero", "0", 0},
34			{"trailing fraction", "8080.0", 8080},
35			{"scientific notation", "8.08e3", 8080},
36			{"above float53", "9007199254740993", 9007199254740993},
37			{"int64 upper bound", "9223372036854775807", 9223372036854775807},
38		}
39		for i, tc := range cases {
40			t.Run(tc.name, func(t *testing.T) {
41				id := fmt.Sprintf("i-%d", i)
42				rec := doRequest(t, router, http.MethodPost, "/api/v1/register",
43					portBody(id, json.Number(tc.raw)))
44				if rec.Code != http.StatusOK {
45					t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
46				}
47				// The success response carries the exact JSON integer.
48				wantJSON := fmt.Sprintf(`"port":%d`, tc.want)
49				if !strings.Contains(rec.Body.String(), wantJSON) {
50					t.Fatalf("response body %s missing %s", rec.Body.String(), wantJSON)
51				}
52				// The stored record keeps the exact integer.
53				got, found, err := st.GetInstance("svc", id)
54				if err != nil || !found {
55					t.Fatalf("stored: found=%v err=%v", found, err)
56				}
57				if got.Port != tc.want {
58					t.Fatalf("stored port = %d, want %d", got.Port, tc.want)
59				}
60				// The public query returns the exact JSON integer.
61				rec = doRequest(t, router, http.MethodGet,
62					"/api/v1/services/svc/instances/"+id, nil)
63				if rec.Code != http.StatusOK {
64					t.Fatalf("get status = %d body %s", rec.Code, rec.Body.String())
65				}
66				if !strings.Contains(rec.Body.String(), wantJSON) {
67					t.Fatalf("get body %s missing %s", rec.Body.String(), wantJSON)
68				}
69			})
70		}
71	}
72	
73	func TestPortNumericStringForms(t *testing.T) {
74		router, st := testRouter(t)
75	
