				strings.Replace(path, "/api/v1/services/svc/", "/api/v1/", 1),
				`{"service_name":"svc","instance_id":"i-1","unknown":1}`)
			if rec.Code != http.StatusOK {
				t.Fatalf("GET %s object body: %d %s", path, rec.Code, rec.Body.String())
			}
			// An empty {} body completed by query parameters.
			base := "/api/v1/instances"
			switch {
			case strings.HasSuffix(path, "/health"):
				base += "/health"
			case strings.HasSuffix(path, "/weight"):
				base += "/weight"
			case strings.HasSuffix(path, "/heartbeat"):
				base += "/heartbeat"
			}
